settings.custom_css:
selector .elementor-container {
  display: flex !important;
  flex-wrap: wrap !important;
  align-items: stretch !important;
}
selector .elementor-row {
  display: flex !important;
  flex-wrap: wrap !important;
  align-items: stretch !important;
}
selector .elementor-column {
  display: flex !important;
  height: auto !important;
}

selector {
  position: relative !important;
  display: flex !important;
  flex-direction: column !important;
  height: 100% !important;
  transition: all 0.35s cubic-bezier(0.16, 1, 0.3, 1) !important;
}
selector:hover {
  transform: translateY(-8px) !important;
}
selector > .elementor-widget-wrap {
  display: flex !important;
  flex-direction: column !important;
  flex-grow: 1 !important;
  height: 100% !important;
  width: 100% !important;
  justify-content: flex-start !important;
}

selector { margin-top: auto !important; width: 100% !important; }
selector .elementor-button { width: 100% !important; transition: all 0.35s cubic-bezier(0.16, 1, 0.3, 1) !important; background-color: #179A9E !important; color: #FFFFFF !important; }
selector .elementor-button:hover { background-color: #102C40 !important; color: #FFFFFF !important; border-color: #102C40 !important; transform: translateY(-2px); box-shadow: 0 8px 18px rgba(16, 44, 64, 0.25) !important; }

